// Existing-rule editor. Imported conditions are data, never executable code.
let ruleSelection=null,ruleHistory=[],selectedRules=new Set();
const propertyNames={28:'Armor level',36:'Pages',105:'Workmanship',131:'Material',159:'Wield skill',160:'Wield requirement',265:'Equipment set',353:'Wield requirement type',370:'Damage rating',371:'Damage resist rating',374:'Critical damage rating',375:'Critical damage resist rating',376:'Healing boost rating',379:'Max health rating',218103808:'Item template ID',218103822:'Equipable slots',218103849:'Level / icon overlay',218103850:'Icon underlay'};
const conditionNames={1:'Text matching',2:'Maximum value',3:'Minimum value',7:'Item class',9:'Matching spells',11:'Slot flags',12:'Exact value',13:'Excluded value',1000:'Character buffed skill minimum',1001:'Free main-pack spaces before pickup',2001:'Buffed missile damage minimum',2003:'Buffed melee damage minimum',2005:'Buffed wand damage minimum',2007:'Total ratings minimum'};
function structural(e){return /^\*|^~~/.test(e.rule.name)}
function ruleEntries(){return [...state.importedRules.map((e,i)=>({e,key:'i'+i})),...state.serverItems.map((e,i)=>({e,key:'s'+i}))].sort((a,b)=>(a.e.order??1e9)-(b.e.order??1e9))}
function ruleEntry(key){if(!key)return null;return key?.[0]==='s'?state.serverItems[+key.slice(1)]:state.importedRules[+key.slice(1)]}
function rememberRules(){ruleHistory.push(JSON.stringify({importedRules:state.importedRules,serverItems:state.serverItems,custom:state.custom}));if(ruleHistory.length>30)ruleHistory.shift()}
function undoRules(){if(!ruleHistory.length)return;Object.assign(state,JSON.parse(ruleHistory.pop()));ruleSelection=null;persist();render()}
function baseline(e){if(!e.original)e.original={rule:UTL.clone(e.rule),enabled:e.enabled,quantity:e.quantity,group:e.group}}
function ruleChanged(){persist();render()}
function toggleRule(key,on){const e=ruleEntry(key);if(!e||structural(e))return;rememberRules();baseline(e);e.enabled=on;ruleChanged()}
function importedGroup(g,on){rememberRules();for(const e of state.importedRules)if(e.group===g&&!structural(e)){baseline(e);e.enabled=on}ruleChanged()}
function selectRule(key){ruleSelection=key;render()}
function ruleSummary(e){const r=e.rule;return `${e.enabled?'Enabled':'Disabled'} · ${({1:'Keep all',2:'Salvage',3:'Sell',4:'Read',10:'Keep '+(e.quantity??r.quantity)})[r.action]||'Action '+r.action} · ${r.requirements.filter(q=>q.type!==9999).map(q=>{let p=UTL.parts(q);return (propertyNames[p[1]]||conditionNames[q.type]||'Condition '+q.type)+': '+(q.type===9?p[2]+' matching spells':p[0])}).join('; ')}`}
function importedPanel(){const entries=ruleEntries(),groups=[...new Set(entries.map(x=>x.e.group))];return `<div class="card"><h3>All existing rules</h3><p>First matching rule wins. Disabling a rule lets later rules try the item; it does not block the item. New equipment targets remain in their equipment menus.</p><p class="muted">Earlier broad rules may collect items outside a later rule's requirements. Original order is preserved. DreamWeave rules also require the DreamWeave master switch.</p><div class="toolbar"><input aria-label="Search all rules" value="${esc(importQuery)}" oninput="filterImported(this.value)" placeholder="Search rules"><button onclick="addServerItem()">+ DreamWeave item</button><button onclick="selectedRuleBulk(true)">Enable selected</button><button onclick="selectedRuleBulk(false)">Disable selected</button><button onclick="undoRules()" ${ruleHistory.length?'':'disabled'}>Undo rule change</button><button onclick="restoreProfileBackup()">Restore previous profile</button><button onclick="useSalvageControls()">Move supported salvage into controls</button><button onclick="useCloakControls()">Move supported cloaks into controls</button></div></div>${ruleSelection?ruleEditor():''}${groups.map(g=>`<details class="spellgroup" open><summary>${esc(g)}</summary><div class="row"><button data-group="${esc(g)}" onclick="bulkRules(this.dataset.group,true)">Enable category</button><button data-group="${esc(g)}" onclick="bulkRules(this.dataset.group,false)">Disable category</button></div>${entries.filter(x=>x.e.group===g).map(({e,key})=>`<div class="checkrow" data-imported="${esc(e.rule.name.toLowerCase())}">${structural(e)?'<span class="badge">Heading / metadata</span>':`<input aria-label="Select ${esc(e.rule.name)} for bulk change" type="checkbox" ${selectedRules.has(key)?'checked':''} onchange="this.checked?selectedRules.add('${key}'):selectedRules.delete('${key}')"><input type="checkbox" aria-label="Enable ${esc(e.rule.name)}" ${e.enabled?'checked':''} onchange="toggleRule('${key}',this.checked)">`}<span>${esc(e.rule.name)}<small>Order ${Number.isInteger(e.order)?e.order+1:'new'} · ${esc(ruleSummary(e).slice(0,220))}</small></span>${structural(e)?'':`<button onclick="selectRule('${key}')">Edit</button>`}</div>`).join('')}</details>`).join('')}`}
function bulkRules(group,on){rememberRules();for(const {e} of ruleEntries())if(e.group===group&&!structural(e)){baseline(e);e.enabled=on}ruleChanged()}
function inputField(label,value,handler,type='text'){return `<label class="field"><span>${esc(label)}</span><input type="${type}" style="width:100%" value="${esc(value)}" onchange="${handler}"></label>`}
function conditionEditor(q,index){let p=UTL.parts(q),known=conditionNames[q.type],title=(propertyNames[p[1]]||known||'Unfamiliar condition '+q.type);let labels=q.type===9?['Spell-name pattern to include','Spell-name pattern to exclude (blank permits extras)','Minimum matching spells']:q.type===1?['Text pattern','Text property ID']:q.type===1000?['Minimum buffed skill','Skill ID']:p.map((_,i)=>i===0?'Value':'Property / parameter '+(i+1));let fields=p.map((v,j)=>conditionChoice(q,j,v)||inputField(labels[j]||'Parameter '+(j+1),v,`editCondition(${index},${j},this.value)`,q.type===9&&j===2||q.type!==1&&q.type!==9&&known?'number':'text')).map((field,j)=>j>0&&q.type!==9?'<details><summary>Advanced parameter</summary>'+field+'</details>':field).join('');return `<details class="spellgroup" open><summary>${esc(title)} · ${esc(q.type===9?p[2]+' spells':p[0].slice(0,100))}</summary>${!known?'<p>Advanced condition: its original type and parameter order are preserved.</p>':''}${fields}</details>`}
function conditionChoice(q,j,v){let p=UTL.parts(q),choices=null;if(j!==0)return '';if(p[1]==='265')choices={...UTL.SETS,...UTL.CLOAKS.sets};if(q.type===7)choices={Armor:2,Clothing:3,Jewelry:4};if(p[1]==='131')choices=UTLDATA.materialIds;if(p[1]==='218103849')choices={'Level potential 1':27700,'Level potential 2':27701,'Level potential 3':27702,'Level potential 4':27703,'Level potential 5':27704,'Essence 150':29734,'Essence 180':29735,'Essence 200':29736};if(!choices)return '';return `<label class="field"><span>${esc(propertyNames[p[1]]||'Item class')}</span><select onchange="editCondition(${ruleEntry(ruleSelection).rule.requirements.indexOf(q)},0,this.value)"><option value="${esc(v)}">Current: ${esc(Object.keys(choices).find(k=>String(choices[k])===v)||v)}</option>${Object.entries(choices).map(([name,id])=>`<option value="${id}">${esc(name)}</option>`).join('')}</select></label>`}
function selectedRuleBulk(on){rememberRules();for(const key of selectedRules){let e=ruleEntry(key);if(e&&!structural(e)){baseline(e);e.enabled=on}}ruleChanged()}
function ruleEditor(){let e=ruleEntry(ruleSelection);if(!e)return '';let r=e.rule;return `<div class="card"><h3>Edit ${esc(r.name)}</h3><p class="summary">${esc(ruleSummary(e))}</p>${overlapWarning(e)}${ruleSelection[0]==='s'?inputField('Set an exact item name (escapes special characters)',exactItemName(r),"setExactItemName(this.value)"):''}${inputField('Rule name',r.name,"editRuleField('name',this.value)")}${inputField('Category',e.group,"editRuleField('group',this.value)")}<label class="field"><span>Action</span><select onchange="editRuleField('action',+this.value)">${[1,2,3,4,10].map(a=>`<option value="${a}" ${a===r.action?'selected':''}>${({1:'Keep all',2:'Salvage',3:'Sell',4:'Read',10:'Keep quantity'})[a]}</option>`).join('')}</select></label>${r.action===10?inputField('Keep quantity',e.quantity??r.quantity,"editRuleField('quantity',this.value)",'number'):''}<p>All conditions below must match. Changing a value preserves the other conditions. Text patterns use the original editor’s regular-expression syntax.</p><details class="spellgroup"><summary>Text matching help</summary><p>For an exact name use ^Item Name$. A pattern such as Red|Blue accepts either. Duplicate a similar existing item to retain its ID and other conditions. Leave spell exclusions blank to permit extra spells.</p></details>${r.requirements.map((q,i)=>q.type===9999?'':conditionEditor(q,i)).join('')}<details class="spellgroup"><summary>Advanced: add a condition</summary><select id="newCondition">${Object.entries(propertyNames).map(([id,name])=>`<option value="${id}">${esc(name)}</option>`).join('')}</select><select id="newComparison"><option value="3">Minimum</option><option value="2">Maximum</option><option value="12">Equals</option><option value="13">Does not equal</option></select><button onclick="addRuleCondition()">Add</button></details><div class="row"><button onclick="duplicateRule()">Duplicate</button><button onclick="resetRule()">Reset to imported values</button><button onclick="ruleSelection=null;render()">Close</button></div></div>`}
function editRuleField(field,value){let e=ruleEntry(ruleSelection);if(!e)return;try{if(['action','quantity'].includes(field)){value=Number(value);if(!Number.isSafeInteger(value)||value<1||value>2147483647)throw Error('Enter a positive whole number.')}if(['name','group'].includes(field)&&(!value.trim()||/[\r\n]/.test(value)))throw Error('Enter a name on one line.');if(ruleSelection[0]==='s'&&field==='action'&&![1,10].includes(value))throw Error('DreamWeave items support Keep all or Keep quantity. Use an existing non-server rule for other actions.');rememberRules();baseline(e);if(field==='group')e.group=value;else if(field==='quantity'){e.quantity=value;e.rule.quantity=value}else e.rule[field]=value;if(field==='action'){e.quantity=value===10?Math.max(1,e.quantity||e.rule.quantity||1):0;e.rule.quantity=value===10?e.quantity:null}delete e.rule.raw;ruleChanged()}catch(err){message('Rule needs attention',err.message)}}
function editCondition(index,part,value){let e=ruleEntry(ruleSelection),q=e.rule.requirements[index],p=UTL.parts(q);if(/[\r\n]/.test(value)){message('Invalid value','Use a single line.');return}rememberRules();baseline(e);p[part]=value;q.data=p.join('\r\n')+'\r\n';delete e.rule.raw;ruleChanged()}
function addRuleCondition(){let e=ruleEntry(ruleSelection);rememberRules();baseline(e);e.rule.requirements.push(UTL.req(+document.getElementById('newComparison').value,0,+document.getElementById('newCondition').value));delete e.rule.raw;ruleChanged()}
function nextRuleOrder(){return Math.max(-1,...ruleEntries().map(x=>x.e.order??-1))+1}
function duplicateRule(){let e=ruleEntry(ruleSelection);rememberRules();let copy=structuredClone(e);delete copy.original;copy.rule=UTL.clone(copy.rule);copy.rule.name+=' copy';copy.order=nextRuleOrder();if(ruleSelection[0]==='s'){state.serverItems.push(copy);ruleSelection='s'+(state.serverItems.length-1)}else{state.importedRules.push(copy);ruleSelection='i'+(state.importedRules.length-1)}ruleChanged()}
function resetRule(){let e=ruleEntry(ruleSelection);if(!e.original)return;rememberRules();Object.assign(e,structuredClone(e.original));ruleChanged()}
function addServerItem(){rememberRules();state.custom=true;state.serverItems.push({group:'Custom DreamWeave items',order:nextRuleOrder(),enabled:false,quantity:0,rule:{name:'New DreamWeave item',expression:'',priority:0,action:1,quantity:null,requirements:[UTL.req(1,'^New item name$',1)]}});ruleSelection='s'+(state.serverItems.length-1);tab='Imported';ruleChanged()}
const originalServerPanel=serverPanel;
serverPanel=function(){return `<div class="card"><button onclick="addServerItem()">+ Add DreamWeave item</button><button onclick="tab='Imported';render()">Edit existing item conditions</button><p>New items start disabled. Set the name pattern or item ID, then enable the rule.</p></div>`+originalServerPanel()};
function backupProfile(){try{localStorage.setItem('broloot-previous-profile',JSON.stringify(snapshot()))}catch(e){throw Error('Could not save a recovery backup. Save settings before replacing this profile.')}}
function restoreProfileBackup(){try{let backup=localStorage.getItem('broloot-previous-profile');if(!backup)throw Error('No previous-profile backup is available.');let next=validateSnapshot(JSON.parse(backup));backupProfile();state=next;originalText='';initIO();ruleSelection=null;ruleHistory=[];selectedRules.clear();persist();render()}catch(e){message('Could not restore profile',e.message)}}
function ruleIssues(e){let issues=[],r=e.rule;for(const q of r.requirements){let p=UTL.parts(q);if([1,9].includes(q.type)){for(const pattern of q.type===9?p.slice(0,2):p.slice(0,1))if(pattern){try{new RegExp(pattern)}catch(err){ // .NET-only expressions may be valid in the game; report for review rather than rewrite.
 if(!/\(\?[a-z-]+\)|\(\?<[^=!]/i.test(pattern))issues.push('Review text pattern: '+err.message)}}}if(conditionNames[q.type]&&![1,9].includes(q.type)&&p.some(v=>v.trim()===''||!Number.isFinite(Number(v))))issues.push('Condition contains an invalid number.');if([2,3,7,11,12,13,1000,1001].includes(q.type)&&p.some(v=>!Number.isSafeInteger(+v)||+v < -2147483648||+v>2147483647))issues.push('Use whole numbers within the supported integer range.');if(q.type===9&&(!Number.isInteger(+p[2])||+p[2]<0))issues.push('Spell count must be a whole number of zero or greater.')}for(const a of r.requirements.filter(q=>q.type===3)){let p=UTL.parts(a);for(const b of r.requirements.filter(q=>q.type===2)){let v=UTL.parts(b);if(p[1]===v[1]&&+p[0]>+v[0])issues.push((propertyNames[p[1]]||'Value')+' minimum exceeds maximum.')}}return issues}

function exactItemName(r){let q=r.requirements.find(q=>q.type===1&&UTL.parts(q)[1]==='1');if(!q)return '';let pattern=UTL.parts(q)[0];return /^\^[\w -]+\$$/.test(pattern)?pattern.slice(1,-1):''}
function setExactItemName(name){if(!name.trim()||/[\r\n]/.test(name)){message('Name required','Enter an item name on one line.');return}let e=ruleEntry(ruleSelection);rememberRules();baseline(e);let q=e.rule.requirements.find(q=>q.type===1&&UTL.parts(q)[1]==='1'),pattern='^'+name.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'$';if(q)q.data=UTL.req(1,pattern,1).data;else e.rule.requirements.push(UTL.req(1,pattern,1));delete e.rule.raw;ruleChanged()}

function overlapWarning(entry){let entries=ruleEntries(),index=entries.findIndex(x=>x.e===entry),signature=q=>q.type+':'+q.data,conditions=new Set(entry.rule.requirements.filter(q=>q.type!==9999&&q.type!==1001).map(signature));let earlier=entries.slice(0,index).find(({e,key})=>e.enabled&&!structural(e)&&(key[0]!=='s'||state.custom)&&!e.rule.expression&&e.rule.requirements.filter(q=>q.type!==9999&&q.type!==1001).every(q=>conditions.has(signature(q))));return earlier?'<p class="notice">Earlier rule “'+esc(earlier.e.rule.name)+'” has the same or fewer item conditions and may match first. Check its action and pack-space requirement.</p>':''}

function resetRuleWorkspace(){ruleSelection=null;ruleHistory=[];selectedRules.clear()}
